written = []
for cid in IDS:
    d = P[cid]
    rec = {"case_id": cid, "prediction_text": d["prediction_text"], "basis": d["basis"],
           "confidence": d["confidence"], "trigger": d["trigger"]}
    with open(os.path.join(OUT, cid + ".json"), "w", encoding="utf-8") as f:
        json.dump(rec, f, ensure_ascii=False, indent=2)
    written.append(cid)

assert len(written) == 20, len(written)
assert set(written) == set(IDS)
for cid in IDS:
    with open(os.path.join(OUT, cid + ".json"), encoding="utf-8") as f:
        r = json.load(f)
    for k in ["case_id","prediction_text","basis","confidence","trigger"]:
        assert k in r, (cid, k)
    assert r["case_id"] == cid
    assert isinstance(r["confidence"], (int, float)) and 0 <= r["confidence"] <= 1
    for b in ["changed_main","reserve_used","disputed"]:
        assert isinstance(r["trigger"][b], bool)
    assert isinstance(r["trigger"]["reason"], str)

cm = sum(1 for c in IDS if P[c]["trigger"]["changed_main"])
ru = sum(1 for c in IDS if P[c]["trigger"]["reserve_used"])
di = sum(1 for c in IDS if P[c]["trigger"]["disputed"])
print("written:", len(written))
print("trigger counts changed_main/reserve_used/disputed =", cm, ru, di)
print("ids ok:", sorted(written) == sorted(IDS))
